/* D03：教学用 CAN 数据布局。不是某款车的协议，不连接实车。
 * 8字节载荷：0、1号字节存车速；2号字节存模式与雷达有效位；其余为0。
 * 车速单位km/h，分辨率0.1，偏移0；低字节先放（Intel小端）。 */
#include <stdio.h>   /* scanf读输入，printf输出；网页把参数交给这个程序。 */
#include <stdint.h>  /* uint8_t为8位无符号数，uint32_t为32位无符号数。 */
#include <stddef.h>  /* size_t表示长度，NULL表示没有可用地址。 */
#include <math.h>    /* isfinite检查有限数，roundf四舍五入float。 */

/* [接口] 先声明函数：编译器读到main调用时，就知道参数和返回类型。
 * int返回状态：0成功，-1地址/长度错，-2数值/协议错。
 * 真正的帧与解码车速经指针写到调用方变量，不能把状态当车速。 */
int Encode(float speed, int mode, int radar, uint8_t *data, size_t length);
int Decode(const uint8_t *data, size_t length, float *speed);

int main(void)
{
    /* [入口] 创建本次输入和输出容器。数组如8个小格，每格只能装0到255。
     * {0}使所有格子从0开始；单独的变量用=0初始化。
     * mode=0速度模式，1间距模式，2故障模式；由上游决定，本课只传输。 */
    float speed = 0.0f;
    int mode = 0, radar = 0, length_input = 0, damage = 0;
    uint8_t data[8] = {0};
    float decoded_speed = 0.0f;
    /* [输入] %f读float，%d读int；&给scanf可写的变量地址。
     * 返回5表示5项都读到了。它与Encode返回0是不同函数的不同约定。 */
    if (scanf("%f %d %d %d %d", &speed, &mode, &radar, &length_input, &damage) != 5) {
        printf("status=-3\nvalid=0\nstage=0\n");
        return 0; /* 结束main；0表示进程正常结束，不表示输入正确。 */
    }
    /* [调用编码] 先查int长度，避免负数转成无符号的巨大正数。
     * 这里8是本协议的固定长度，不是靠指针推测出来的。 */
    if (length_input != 8) {
        printf("status=-1\nvalid=0\nstage=1\n");
        return 0;
    }
    int status = Encode(speed, mode, radar, data, (size_t)length_input);
    printf("status=%d\nvalid=%d\nstage=1\n", status, status == 0);
    if (status != 0) return 0; /* 失败就停止，不把未完成的帧交给下游。 */
    /* [观察帧] %02X按十六进制显示，至少两位；十进制213显示为D5。
     * printf的%X需要unsigned int，所以做明确转换；不改变数值。 */
    printf("raw=%u\n", (unsigned int)((uint32_t)data[0] | ((uint32_t)data[1] << 8)));
    printf("frame=");
    for (size_t i = 0; i < 8; i++) {
        printf("%02X%s", (unsigned int)data[i], i == 7 ? "\n" : " ");
        /* 条件 ? A : B：条件为真选A，否则选B；最后一格换行，其余加空格。 */
    }
    /* [接收实验] 模拟传输中模式位损坏：把低2位改成二进制11（值3）。
     * 不连接CAN设备；页面显示的是发送前的帧，解码读取这里修改后的帧。 */
    if (damage == 1) data[2] = (uint8_t)(data[2] | 3u);
    status = Decode(data, 8, &decoded_speed);
    printf("decode_status=%d\ndecode_valid=%d\nreceived_control=%u\n", status, status == 0, (unsigned int)data[2]);
    if (status == 0) printf("decoded_speed=%.1f\n", (double)decoded_speed);
    return 0;
}

int Encode(float speed, int mode, int radar, uint8_t *data, size_t length)
{
    /* [编码守门] 先拒绝，后写输出：失败时不产生半个新帧。
     * ||是“任一成立”；isfinite返回非0表示有限，!把真变假、假变真。
     * NaN不是普通负数；它不适合只用<0、>250检测。 */
    if (data == NULL || length != 8) return -1;
    if (!isfinite(speed) || speed < 0.0f || speed > 250.0f) return -2;
    if (mode < 0 || mode > 2 || radar < 0 || radar > 1) return -2;
    /* [量化] 物理量=原始整数×0.1，所以原始整数=车速÷0.1。
     * 写×10减少小数除法；roundf先取最近整数，再转uint32_t。
     * 72.5×10=725。u表示无符号整数常量；f表示float常量。 */
    uint32_t raw = (uint32_t)roundf(speed * 10.0f);
    /* [拆字节] &是按位与，不是这里的取地址：保留掩码为1的位置。
     * 255=0xFF=低8位全1。raw&255取低8位；raw>>8丢掉低8位。
     * 725=2×256+213，所以byte0=213(D5)，byte1=2(02)。 */
    data[0] = (uint8_t)(raw & 255u);
    data[1] = (uint8_t)((raw >> 8) & 255u);
    /* [合控制位] |为按位或；<<2把雷达位移到bit2（权重4）。
     * 模式占bit0、bit1；雷达占bit2。mode1、radar1 => 1|4=5。
     * 已校验范围，两部分不重叠，所以本课也可用mode+radar×4验算。 */
    data[2] = (uint8_t)((uint32_t)mode | ((uint32_t)radar << 2));
    for (size_t i = 3; i < 8; i++) data[i] = 0;
    return 0;
}

int Decode(const uint8_t *data, size_t length, float *speed)
{
    /* [解码守门] const表示只读载荷；speed是要写回的车速地址。
     * 指针自身不含数组长度，length由调用方传入。
     * 248=11111000，检查bit3到bit7这些保留位；&3提取低2位模式。 */
    if (data == NULL || speed == NULL || length != 8) return -1;
    if ((data[2] & 248u) != 0 || (data[2] & 3u) > 2u) return -2;
    for (size_t i = 3; i < 8; i++) if (data[i] != 0) return -2;
    /* [拼回车速] 先把高字节提升到32位再左移8位，相当于乘256。
     * 高低位不重叠，按位或拼成原始数。D5 02 => 213+2×256=725。
     * *speed放在赋值左边表示写入指针指向的位置，不是乘号。 */
    uint32_t raw = (uint32_t)data[0] | ((uint32_t)data[1] << 8);
    if (raw > 2500u) return -2;
    *speed = (float)raw * 0.1f;
    return 0;
}
